/**
 * Icons for the Classic Green LCD theme in old-phone 1-bit line art: solid pixel outlines, no shading.
 * The launcher's own icons are hand-drawn on a 20×20 grid; app icons are traced into outlines from
 * their emblem. Ink is stored white because the LCD screen filter turns brightness around.
 */
object LcdPixelizer {
    private const val N = 24       // dots per side of an icon
    private const val SCALE = 5
    private const val INK = 0xFFFFFFFF.toInt()

    private val grids = mapOf(
        "msg" to "....................|..################..|.#................#.|#..................#|#..##############..#|#..................#|#..##########......#|#..................#|#..############....#|#..................#|.#................#.|..####..##########..|.....#.#............|.....##.............|.....#..............|....................|....................|....................|....................|....................",
        "mail" to "....................|....................|....................|####################|##................##|#.#..............#.#|#..#............#..#|#...#..........#...#|#....#........#....#|#.....#......#.....#|#......#.####......#|#.....#......#.....#|#....#........#....#|#...#..........#...#|#..#............#..#|#.#..............#.#|####################|....................|....................|....................",
        "cal" to "....##......##......|....##......##......|.##################.|.#................#.|.##################.|.#................#.|.#..##..##..##..#.#.|.#................#.|.#..##..##..##..#.#.|.#................#.|.#..##..##..####..#.|.#..........####..#.|.#..##..##........#.|.#................#.|.##################.|....................|....................|....................|....................|....................",
        "person" to ".......######.......|......#......#......|.....#........#.....|.....#........#.....|.....#........#.....|.....#........#.....|......#......#......|.......######.......|....................|....############....|...#............#...|..#..............#..|.#................#.|.#................#.|.#................#.|.##################.|....................|....................|....................|....................",
        "bell" to ".........##.........|........####........|......##....##......|.....#........#.....|....#..........#....|....#..........#....|....#..........#....|....#..........#....|....#..........#....|...#............#...|..#..............#..|.##################.|........#..#........|.........##.........|....................|....................|....................|....................|....................|....................",
        "apps" to "....................|.######....######...|.#....#....#....#...|.#....#....#....#...|.#....#....#....#...|.#....#....#....#...|.######....######...|....................|....................|.######....######...|.#....#....#....#...|.#....#....#....#...|.#....#....#....#...|.#....#....#....#...|.######....######...|....................|....................|....................|....................|....................",
        "settings" to "........####........|...##...#..#...##...|...#.###....###.#...|...#............#...|....#...####...#....|..###..#....#..###..|.#....#......#....#.|.#....#......#....#.|..###..#....#..###..|....#...####...#....|...#............#...|...#.###....###.#...|...##...#..#...##...|........####........|....................|....................|....................|....................|....................|....................",
        "usage" to "....................|#...................|#..............###..|#..............#.#..|#..............#.#..|#.........###..#.#..|#.........#.#..#.#..|#.........#.#..#.#..|#....###..#.#..#.#..|#....#.#..#.#..#.#..|#....#.#..#.#..#.#..|#....#.#..#.#..#.#..|####################|....................|....................|....................|....................|....................|....................|....................",
        "card" to "....................|....................|....................|.##################.|.#................#.|.#................#.|.##################.|.##################.|.#................#.|.#..####..........#.|.#................#.|.#..######..####..#.|.#................#.|.##################.|....................|....................|....................|....................|....................|....................",
        "calc" to "...##############...|..#..............#..|..#.############.#..|..#.#..........#.#..|..#.#.......##.#.#..|..#.############.#..|..#..............#..|..#.##..##..##...#..|..#..............#..|..#.##..##..##...#..|..#..............#..|..#.##..##..####.#..|..#.........####.#..|..#.##..##..####.#..|..#..............#..|...##############...|....................|....................|....................|....................",
        "clock" to ".......######.......|.....##......##.....|....#....##....#....|...#.....##.....#...|..#......##......#..|..#......##......#..|.#.......##.......#.|.#.......##.......#.|.#.......######...#.|.#................#.|..#..............#..|..#..............#..|...#............#...|....#..........#....|.....##......##.....|.......######.......|....................|....................|....................|....................",
        "battery" to "....................|....................|....................|....................|.################...|.#..............#...|.#.##.##.##.....###.|.#.##.##.##.....#.#.|.#.##.##.##.....#.#.|.#.##.##.##.....###.|.#..............#...|.################...|....................|....................|....................|....................|....................|....................|....................|....................",
        "call" to "....................|..####..............|..#..#..............|..#..#..............|..#..#..............|...#..#.............|...#...#............|....#...#...........|.....#...##..####...|......#....##...#...|.......#........#...|........##......#...|..........######....|....................|....................|....................|....................|....................|....................|....................",
        "camera" to "....................|....................|.......######.......|..#####......#####..|..#..............#..|..#.....####.....#..|..#....#....#..#.#..|..#...#......#...#..|..#...#......#...#..|..#...#......#...#..|..#....#....#....#..|..#.....####.....#..|..#..............#..|..################..|....................|....................|....................|....................|....................|....................",
        "desktop" to "....................|.##################.|.#................#.|.#................#.|.#................#.|.#................#.|.#................#.|.#................#.|.#................#.|.##################.|........#..#........|........#..#........|.....##########.....|....................|....................|....................|....................|....................|....................|...................."
    )

    private fun place(ink: Array<BooleanArray>, w: Int, h: Int): Bitmap {
        // Trim and centre on the N×N canvas.
        var l = w; var t = h; var r = -1; var b = -1
        for (y in 0 until h) for (x in 0 until w) if (ink[y][x]) { if (x < l) l = x; if (x > r) r = x; if (y < t) t = y; if (y > b) b = y }
        val px = IntArray(N * N)
        if (r >= 0) {
            val ox = (N - (r - l + 1)) / 2 - l; val oy = (N - (b - t + 1)) / 2 - t
            for (y in t..b) for (x in l..r) if (ink[y][x]) { val X = x + ox; val Y = y + oy; if (X in 0 until N && Y in 0 until N) px[Y * N + X] = INK }
        }
        return Bitmap.createScaledBitmap(Bitmap.createBitmap(px, N, N, Bitmap.Config.ARGB_8888), N * SCALE, N * SCALE, false)
    }

    private val builtIn = HashMap<String, ImageBitmap>()
    fun builtIn(name: String): ImageBitmap? = synchronized(builtIn) {
        builtIn[name] ?: grids[name]?.let { g ->
            val rows = g.split('|'); val h = rows.size; val w = rows[0].length
            place(Array(h) { y -> BooleanArray(w) { x -> rows[y][x] == '#' } }, w, h).asImageBitmap()
        }?.also { builtIn[name] = it }
    }

    /** Any app icon → outline drawing of its emblem (tile removed), plus its dark details and colour edges. */
    fun convert(d: Drawable): Bitmap = convert(S60Styler.emblem(d))

    fun convert(src: Bitmap): Bitmap {
        val n = N - 2
        val big = Bitmap.createScaledBitmap(src, n * 4, n * 4, true)
        val s = Bitmap.createScaledBitmap(big, n, n, true)
        val px = IntArray(n * n); s.getPixels(px, 0, n, 0, 0, n, n)
        val solid = BooleanArray(n * n) { (px[it] ushr 24) > 110 }
        val lum = FloatArray(n * n) { val c = px[it]; (0.299f * (c shr 16 and 0xFF) + 0.587f * (c shr 8 and 0xFF) + 0.114f * (c and 0xFF)) / 255f }
        val ink = Array(n) { BooleanArray(n) }
        fun at(x: Int, y: Int) = x in 0 until n && y in 0 until n && solid[y * n + x]
        for (y in 0 until n) for (x in 0 until n) {
            val i = y * n + x; if (!solid[i]) continue
            if (!at(x + 1, y) || !at(x - 1, y) || !at(x, y + 1) || !at(x, y - 1)) { ink[y][x] = true; continue }
            if (lum[i] < 0.28f) { ink[y][x] = true; continue }
            for ((dx, dy) in listOf(1 to 0, 0 to 1)) {
                val xx = x + dx; val yy = y + dy
                if (!at(xx, yy)) continue
                val j = yy * n + xx
                if (Math.abs(lum[i] - lum[j]) > 0.22f) { if (lum[i] < lum[j]) ink[y][x] = true else ink[yy][xx] = true }
            }
        }
        return place(ink, n, n)
    }
}

/** A launcher icon (Messages, Calendar …) as 1-bit LCD line art. */
@Composable
fun LcdIcon(name: String, modifier: Modifier = Modifier) {
    val bmp = remember(name) { LcdPixelizer.builtIn(name) } ?: return
    Image(bmp, contentDescription = null, modifier = modifier.size(32.dp), contentScale = ContentScale.Fit, filterQuality = FilterQuality.None)
}
